/* The first story chapter. All progress belongs to the active local profile. */
const STORY_STEPS=['В дорогу','Знакомство','Книга рецептов','Наряды','Первые слова','В гостях','История у костра','Праздник','Дома Южного Урала'];
// Stable scene IDs keep saved journeys and teacher analytics compatible.
const STORY_ORDER = [0, 1, 2, 3, 8, 4, 5, 6, 7];
function storyStepIndex(s) { return Math.max(0, STORY_ORDER.indexOf(Number(s?.step))); }
const STORY_RECIPES=[
 {id:'chakchak',name:'Чак-чак',intro:'Сладкое угощение из кусочков теста с медовой заливкой. Его готовят в разных семьях Башкортостана и Татарстана. Размер и форма кусочков могут отличаться.',items:['Подготовить тесто','Обжарить кусочки теста','Соединить с медовой заливкой'],note:'Мы собираем карточки рецепта в игре. Настоящую готовку с горячим маслом и сиропом выполняют взрослые.'},
 {id:'beshbarmak',name:'Бешбармак',intro:'Блюдо из мяса и теста, распространённое у нескольких тюркских народов. У семьи Данияра к нему подают бульон. Семейных вариантов много.',items:['Подготовить мясо и бульон','Отварить кусочки теста','Подать мясо и тесто с бульоном'],note:'Это упрощённая схема подачи, а не единственный правильный рецепт.'},
 {id:'tukmach',name:'Тукмас (тукмач)',intro:'Домашняя лапша и суп с ней. В семье Данияра тонко раскатанное тесто нарезают полосками и добавляют в бульон.',items:['Раскатать тесто','Нарезать лапшу','Добавить лапшу в бульон'],note:'Тукмач встречается и в башкирской, и в татарской кухне. Рецепты различаются.'}
];
const STORY_WORDS=[{word:'Һаумыһығыҙ!',meaning:'Здравствуйте',hint:'Так вежливо приветствуют нового знакомого.'},{word:'Рәхмәт!',meaning:'Спасибо',hint:'Так благодарят за помощь.'},{word:'Һау бул!',meaning:'До свидания',hint:'Так прощаются с другом.'}];
const STORY_GRANDMA=[
 {id:'origins',question:'Откуда появились башкиры?',answer:'История народа складывалась веками. В формировании башкир участвовали разные группы населения Южного Урала и пришедшие сюда тюркские племена. Учёные сопоставляют язык, археологические находки и письменные источники. У народа нет одного «дня рождения», а легенды о происхождении не заменяют историческое исследование.'},
 {id:'today',question:'А как люди живут сейчас?',answer:'Сегодня в Башкортостане живут люди разных национальностей. Они учатся, работают, создают музыку и технологии, занимаются спортом и сохраняют семейные традиции. Уфа — столица республики. Современная жизнь не ограничивается праздничным костюмом, юртой или старинным ремеслом.'},
 {id:'honey',question:'Почему здесь говорят о мёде?',answer:'В Башкортостане развиты разные виды пчеловодства. Особая традиция — бортничество: содержание пчёл в древесных полостях, бортях. Это требует знаний о лесе и пчёлах. Не каждый житель занимается этим ремеслом, но оно стало важной частью культурного наследия региона.'},
 {id:'kurai',question:'Как звучит курай?',answer:'Курай — башкирский духовой инструмент, продольная флейта. Его традиционно делают из стебля растения; сегодня используют и другие материалы. Исполнитель направляет воздух и закрывает отверстия пальцами. Нажми «Попробовать звук», чтобы услышать условный электронный звук — это не запись настоящего курая.'}
];
function storyState(u){
 const old=u.story&&typeof u.story==='object'?u.story:{};
 u.story=Object.assign({version:1,step:0,cooking:{},recipe:0,outfits:{},outfit:0,pieces:[],words:[],word:0,grandma:[],branch:null,epic:null,feedback:'',completed:false,rewards:[]},old);
 const s=u.story;s.step=STORY_ORDER[storyStepIndex(s)];s.recipe=Math.min(2,Math.max(0,Math.floor(Number(s.recipe)||0)));s.word=Math.min(4,Math.max(0,Math.floor(Number(s.word)||0)));
 if(!s.cooking||typeof s.cooking!=='object')s.cooking={};if(!s.outfits||typeof s.outfits!=='object')s.outfits={};
 for(const key of ['words','grandma','rewards'])if(!Array.isArray(s[key]))s[key]=[];
 return s;
}
function storyHuman(grandmother=false){return `<span class="story-human story-human-sprite story-host-sprite ${grandmother?'grandma':'daniyar'}" role="img" aria-label="${grandmother?'Бабушка Данияра':'Данияр — вымышленный герой путешествия'}"></span>`}
function storyOutfitSvg(which,parts=[]){const has=n=>parts.includes(n),color=which===0?'#73947e':'#bd7c70';return `<svg viewBox="0 0 210 280" class="story-outfit-figure" role="img" aria-label="${which===0?'Игровой мужской наряд':'Игровой женский наряд'}: собрано ${parts.length} из трёх частей"><path d="M73 62L42 93 24 146l28 13 24-38v113h61V121l24 38 28-13-18-53-31-31Z" fill="#dcdccb" stroke="#a7ae94" stroke-width="2" stroke-dasharray="5 5"/>${has('body')?`<path d="M73 62L42 93 24 146l28 13 24-38v113h61V121l24 38 28-13-18-53-31-31Z" fill="${color}" stroke="#566a55" stroke-width="2"/>`:''}${has('collar')?'<path d="M80 65l25 34 26-34-12-8-14 15-14-15Z" fill="#f7e7bf" stroke="#b39259" stroke-width="2"/>':''}${has('hem')?`<path d="M76 198h61v36H76Z" fill="#e7bd6c"/>`:''}<circle cx="105" cy="32" r="22" fill="#e6b88f"/><path d="M85 24q20-28 40 0" fill="#6b513c"/><path d="M86 235v30h16v-30m9 0v30h17v-30" fill="#667085"/></svg>`}
function storyBooklet(){return `<section class="story-booklet game-panel"><div class="story-map-outline" id="storyOutline" aria-label="Контур Башкортостана"><span>${kidIcon('compass')}</span></div><div class="story-booklet-copy"><h3>Башкортостан</h3><p>Мы на Южном Урале и в Предуралье. Столица республики — Уфа. Здесь живут башкиры, русские, татары и представители других народов.</p><p>Данияр и его бабушка — вымышленные герои. Они приглашают нас познакомиться с культурой через семейную историю подготовки к празднику.</p></div></section>`}
function storyCanNext(s){if(s.step===2)return STORY_RECIPES.every(r=>s.cooking[r.id]?.length===3);if(s.step===3)return [0,1].every(i=>s.outfits[i]?.length===3);if(s.step===8)return visitRoomsComplete(s);if(s.step===4)return s.words.length>=5;if(s.step===5)return s.dinnerDone?.length===4;if(s.step===6)return !!(s.campfire?.done||s.campfire?.legacySkip||s.legendRead);return true}
function storyBody(u,s){
 if(s.step===0)return `<div class="story-scene"><div class="story-landscape"><img src="assets/ural-postcard.jpg" alt="Иллюстрированный Южный Урал: река, горы и лес"></div><div class="story-explorer">${gameCharacter(u)}</div><div class="story-guide-lynx">${visitCompanionMarkup()}</div></div><section class="story-dialogue game-panel"><h2>${esc(u.nick)}, отправимся в путешествие?</h2><p>Твой герой уже собран, рюкзак готов. На Южном Урале нас ждёт Данияр: он помогает семье подготовиться к Сабантую. Вместе узнаем новые слова, соберём наряды и заглянем в книгу рецептов.</p><p>Все открытия сохранятся в этом браузере. Можно остановиться и вернуться позже.</p></section>`;
 if(s.step===1)return storyBooklet();
 if(s.step===2)return renderVisitCooking(u,s);
 if(s.step===3)return renderVisitPatterns(u,s);
 if(s.step===8)return renderVisitRooms(s);
 if(s.step===4)return visitLanguagePage(u,s);
 if(s.step===5)return visitDinnerPage(u,s);
 if(s.step===6)return visitCampfirePage(u,s);
 return `<div class="story-scene"><div class="story-landscape"><img src="assets/ural-postcard.jpg" alt="Праздничная поляна Южного Урала"></div><div class="story-explorer">${gameCharacter(u)}</div><div class="story-host">${storyHuman()}</div></div><section class="story-dialogue game-panel"><h2>${s.completed?'До новых встреч!':'Праздник получился!'}</h2><p>«Рәхмәт, ${esc(u.nick)}! С твоей помощью готовы угощения и наряды. А ещё мы поговорили о языке, истории и музыке. Теперь ты наш друг», — говорит Данияр.</p><p>${s.completed?'Два подарка уже в твоей коллекции. Можно вернуться к ним в профиле.':'На Сабантуе можно поделиться с гостем одним из своих открытий.'}</p></section>${visitFestivalScene(s)}<div class="story-reward-grid"><article class="game-panel"><span class="story-reward-icon story-hat">${storyRewardIcon('burek')}</span><h3>Бүрек</h3><p>Игровая меховая шапка для твоего персонажа. Варианты названия и формы головных уборов различаются.</p></article><article class="game-panel"><span class="story-reward-icon">${storyRewardIcon('kurai')}</span><h3>Значок «Курай»</h3><p>Память о музыке Южного Урала — для коллекции и рюкзака путешественника.</p></article></div>${s.completed?'<div class="story-complete-actions"><a class="kid-primary" href="#profile">Посмотреть подарки '+kidIcon('arrow')+'</a><p lang="ba">Һау бул, Данияр!</p><p>Пора открывать следующие регионы. Спутник проводит тебя к карте.</p><a class="btn secondary" href="#map">В следующие путешествия →</a><button type="button" class="btn secondary" data-story-replay>Пройти историю ещё раз</button></div>':'<div class="story-complete-actions"><button type="button" class="kid-primary" data-story-finish ' + (visitFestivalChoices(s).some(([id])=>id===s.sharedDiscovery)?'':'disabled') + ' >Забрать подарки '+kidIcon('star')+'</button></div>'}`;
}
function storyRewardIcon(which){if(which==='burek')return '<svg viewBox="0 0 100 100" aria-hidden="true"><path d="M20 55Q17 18 50 16q33 2 30 39" fill="#9d7752" stroke="#6c5339" stroke-width="3"/><path d="M13 54q7-10 15-3 7-9 15-2 8-8 15 0 10-7 17 2 9-6 13 5v18q-38 17-75 0Z" fill="#66513d" stroke="#4c4538" stroke-width="3"/><path d="M23 58v12m12-14v17m13-18v19m13-19v18m13-16v13" stroke="#b59b76" stroke-width="3" stroke-linecap="round"/></svg>';return '<svg viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="40" fill="#e5be63" stroke="#b2914a" stroke-width="3"/><path d="M44 21h12v61H44Z" fill="#947447" stroke="#76572d" stroke-width="2"/><path d="M47 23v55" stroke="#e3c88a" stroke-width="2"/><g fill="#5e4e31"><circle cx="50" cy="43" r="2"/><circle cx="50" cy="52" r="2"/><circle cx="50" cy="61" r="2"/><circle cx="50" cy="70" r="2"/></g><path d="M66 35q12 12 0 24m7-31q20 19 0 38" fill="none" stroke="#8b733b" stroke-width="3" stroke-linecap="round"/></svg>'}
function storyPage(u){const s=storyState(u),index=storyStepIndex(s);if(s.step===6)s.campfire??={slots:[null,null,null,null],locked:[],legacySkip:s.legendChoice==='no'};return `<div class="story-game game-world" id="storyGame"><div class="story-topbar"><a class="btn secondary" href="#region">← К маршруту</a><div class="story-progress"><span>${STORY_STEPS[s.step]} · ${index+1} из ${STORY_ORDER.length}</span><progress value="${s.completed&&s.step===7?STORY_ORDER.length:index}" max="${STORY_ORDER.length}" aria-label="Прогресс истории"></progress></div><span class="story-save-note">Прогресс сохраняется</span></div>${storyBody(u,s)}${s.step!==5?`<p class="story-feedback" id="storyFeedback" tabindex="-1" role="status">${esc(s.feedback||'')}</p>`:''}${s.step!==7?`<div class="story-actions">${s.step?'<button type="button" class="btn secondary" data-story-back>← Назад</button>':''}<button type="button" class="kid-primary" data-story-next ${storyCanNext(s)?'':'disabled'}>${s.step===0?'Отправиться в Башкортостан':s.step===6?'На праздник!':'Продолжить'} ${kidIcon('arrow')}</button>${!storyCanNext(s)?'<p>Заверши задания этой остановки, чтобы продолжить.</p>':''}</div>`:''}<details class="story-sources"><summary>Об истории и материалах</summary><p>Данияр, бабушка и их подготовка к Сабантую — вымышленный сюжет. «Живая вода» — отдельный эпизод башкирского эпоса «Урал-батыр», который рассказывают у костра. Игровые наряды и рецепты упрощены. Культурные традиции разнообразны; блюда встречаются у разных народов.</p><p><a href="https://basic.bashlang.ru/grammar/paragraph/1/" target="_blank" rel="noopener">Алфавит башкирского языка</a> · <a href="https://assembly.kz/ru/ethnos/ru/bashkiry/" target="_blank" rel="noopener">Материалы об этногенезе башкир</a> · <a href="https://basic.bashlang.ru/vocabulary/topic/1/" target="_blank" rel="noopener">Приветствия и благодарность</a> · <a href="https://www.culture.ru/events/1433016/spektakl-ural-batyr?location=russia" target="_blank" rel="noopener">Сюжет Урал-батыра</a> · <a href="https://www.culture.ru/live/movies/71732/master-klass-domashnyaya-lapsha-dlya-soldat" target="_blank" rel="noopener">Домашняя лапша</a> · <a href="#sources">Материалы маршрута</a></p></details></div>`}
function wireStoryGame(u){
 const root=document.querySelector('#storyGame');if(!root)return;const s=storyState(u);visitTrackScene(u,s.step);
 const redraw=(focusSelector)=>{save();root.outerHTML=storyPage(u);wireStoryGame(u);if(focusSelector)document.querySelector(focusSelector)?.focus({preventScroll:true})};
 const bind=(selector,handler)=>root.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>handler(b)));
 bind('[data-story-next]',()=>{if(!storyCanNext(s))return;visitRecord(u,'complete',{scene:s.step});s.step=STORY_ORDER[storyStepIndex(s)+1];s.feedback='';redraw();document.querySelector('#storyGame')?.scrollIntoView({block:'start',behavior:'instant'})});
 bind('[data-story-back]',()=>{s.step=STORY_ORDER[Math.max(0,storyStepIndex(s)-1)];s.feedback='';redraw()});
 bind('[data-recipe]',b=>{s.recipe=+b.dataset.recipe;s.feedback='';redraw('[data-recipe="'+s.recipe+'"]')});
 bind('[data-cook]',b=>{const r=STORY_RECIPES[s.recipe],items=s.cooking[r.id]||(s.cooking[r.id]=[]),index=+b.dataset.cook;if(index===items.length){items.push(index);s.feedback=items.length===3?'Готово! Страница рецепта восстановлена. Выбери следующее блюдо.':'Верно! Что будет следующим шагом?'}else s.feedback='Пока рано. Сначала: '+r.items[items.length]+'.';redraw('#storyFeedback')});
 bind('[data-piece]',b=>{s.piece=b.dataset.piece;s.feedback='Деталь выбрана. Теперь нажми на подходящее место в этом наряде.';redraw('[data-slot="'+s.piece+'"]')});
 bind('[data-slot]',b=>{if(s.piece===b.dataset.slot){const [outfit,piece]=s.piece.split(':');const parts=s.outfits[outfit]||(s.outfits[outfit]=[]);if(!parts.includes(piece))parts.push(piece);s.piece=null;s.feedback=parts.length===3?'Наряд собран! Ты отлично справился.':'Деталь на месте! Выбери следующую.'}else s.feedback=s.piece?'Эта деталь подходит к другому месту или наряду. Попробуй ещё раз.':'Сначала выбери деталь под эскизом.';redraw('#storyFeedback')});
 bind('[data-word]',b=>{s.word=+b.dataset.word;s.feedback='';redraw('[data-word="'+s.word+'"]')});
 bind('[data-meaning]',b=>{if(b.dataset.meaning===STORY_WORDS[s.word].meaning){if(!s.words.includes(s.word))s.words.push(s.word);s.feedback='Верно! '+STORY_WORDS[s.word].word+' — '+STORY_WORDS[s.word].meaning.toLowerCase()+'.'}else s.feedback='Попробуй ещё раз. Подсказка: '+STORY_WORDS[s.word].hint;redraw('#storyFeedback')});
 bind('[data-grandma]',b=>{s.branch=b.dataset.grandma;if(!s.grandma.includes(s.branch))s.grandma.push(s.branch);s.feedback='';redraw('[data-grandma="'+s.branch+'"]')});
 bind('[data-epic]',b=>{s.epic=b.dataset.epic;s.feedback='';redraw('[data-epic="'+s.epic+'"]')});
 bind('[data-kurai-sound]',async b=>{const AudioCtx=window.AudioContext||window.webkitAudioContext;if(!AudioCtx){s.feedback='В этом браузере звук недоступен. Это не мешает продолжить историю.';redraw();return}try{const ctx=new AudioCtx();await ctx.resume();[392,440,523.25,440,392].forEach((frequency,i)=>{const osc=ctx.createOscillator(),g=ctx.createGain(),time=ctx.currentTime+i*.28;osc.type='sine';osc.frequency.value=frequency;g.gain.setValueAtTime(0,time);g.gain.linearRampToValueAtTime(.08,time+.04);g.gain.linearRampToValueAtTime(0,time+.26);osc.connect(g);g.connect(ctx.destination);osc.start(time);osc.stop(time+.28)});b.disabled=true;setTimeout(()=>{ctx.close();if(b.isConnected)b.disabled=false},1600)}catch{b.textContent='Не удалось включить звук'}});
 bind('[data-share-discovery]',button=>{const choice=button.dataset.shareDiscovery;if(!visitFestivalChoices(s).some(([id])=>id===choice))return;s.sharedDiscovery=choice;redraw('#festival-response')});
 bind('[data-story-finish]',()=>{if(!visitFestivalChoices(s).some(([id])=>id===s.sharedDiscovery))return;if(!STORY_RECIPES.every(r=>s.cooking[r.id]?.length===3)||![0,1].every(i=>s.outfits[i]?.length===3)||s.words.length<5||s.dinnerDone?.length!==4){s.feedback='Сначала заверши задания маршрута. К ним можно вернуться кнопкой ниже.';s.step=2;redraw();return}visitRecord(u,'finish');visitRecord(u,'complete',{scene:7});s.completed=true;s.completedAt=s.completedAt||new Date().toISOString();s.rewards=['burek','kurai'];u.rewards=Array.isArray(u.rewards)?u.rewards:[];for(const reward of s.rewards)if(!u.rewards.includes(reward))u.rewards.push(reward);s.feedback='Бүрек и значок «Курай» добавлены в твою коллекцию!';redraw()});
 bind('[data-story-replay]',()=>{const rewards=s.rewards.slice(),completed=s.completed,completedAt=s.completedAt;u.story={step:0,completed,rewards,completedAt};redraw()});
 wireVisitCooking(u,s,redraw);wireVisitPatterns(u,s,redraw);wireVisitRooms(s,redraw);wireVisitNarrative(u,s,redraw);wireVisitCampfire(u,s,redraw);
 const outline=root.querySelector('#storyOutline');if(outline)fetch('assets/russia-map.json').then(r=>r.json()).then(data=>{if(!outline.isConnected)return;const region=data.regions.find(v=>v.id==='bashkortostan');if(!region)return;outline.innerHTML=`<svg role="img" aria-label="Географический контур Башкортостана"><path d="${region.d}" fill="#d9c17b" stroke="#7f8d5f" stroke-width="1"/></svg>`;const svg=outline.querySelector('svg'),box=svg.querySelector('path').getBBox();svg.setAttribute('viewBox',`${box.x-8} ${box.y-8} ${box.width+16} ${box.height+16}`)}).catch(()=>{});
}
